SOURCES=json.loads("{\"paths.py\":\"\\\"\\\"\\\"既存WORLD励振観測の固定位置。\\\"\\\"\\\"\\nfrom pathlib import Path\\nimport sys\\nHERE=Path(__file__).resolve().parent\\nROOT=HERE.parents[1];REPO=ROOT.parents[2]\\nsys.path.insert(0,str(ROOT))\\nfrom budget import read,digest,encode\\nfrom temporary_storage import ManagedStorageBudget as Budget\\nNAME='world-excitation-audit-v1'\\nPERIOD=ROOT/'campaigns/nas-source-period-audit-20261008-v1'\\nCONVERT=ROOT/'campaigns/nas-mcp-postfilter-20261008-v1/runtime-bundle'\\nPRIMARY=ROOT/'campaigns/nas-world-control-20261004-v1/upstream'\\nPYTHON=REPO/'research/experiments/autonomous-speech-synthesis/.venv-eval/bin/python'\\n\",\"observer.cpp\":\"// 追加観測は専用バッファのみを書き込む。元WORLDの状態・係数を変更しない。\\n#include <cmath>\\n#include <cstring>\\nstatic int obs_length=0,obs_count=0,obs_cursor=0;\\nstatic int *obs_index,*obs_noise;\\nstatic unsigned char *obs_vuv,*obs_emit;\\nstatic double *obs_shift,*obs_ap,*obs_norm,*obs_periodic,*obs_aperiodic;\\nstatic void ObsTime(int count,int length,const int *index,const double *shift,const double *vuv) {\\n  obs_count=count;\\n  for(int i=0;i<count;++i){obs_index[i]=index[i];obs_shift[i]=shift[i];}\\n  for(int i=0;i<length;++i)obs_vuv[i]=vuv[i]>0.5;\\n}\\nstatic void ObsResponse(int size,int noise,double vuv,double ap,const double *p,const double *a) {\\n  int cursor=obs_cursor++,offset=obs_index[cursor]-size/2+1;\\n  double norm=0.,scale=std::sqrt(static_cast<double>(noise));\\n  for(int i=0;i<size;++i)norm+=p[i]*p[i];\\n  obs_noise[cursor]=noise;obs_ap[cursor]=ap;obs_norm[cursor]=norm;\\n  obs_emit[cursor]=(vuv>0.5 && norm>0. && noise>0);\\n  int lower=offset<0?-offset:0,upper=size<obs_length-offset?size:obs_length-offset;\\n  for(int i=lower;i<upper;++i){obs_periodic[i+offset]+=p[i]*scale/size;obs_aperiodic[i+offset]+=a[i]/size;}\\n}\\n#define Synthesis ObservedSynthesis\\n#include \\\"synthesis_observed.cpp\\\"\\n#undef Synthesis\\nextern \\\"C\\\" int ObsRun(const double *f0,int n,const double * const *sp,const double * const *ap,\\n int fft,double frame,int fs,int length,double *wave,int *index,double *shift,int *noise,\\n double *ratio,double *norm,unsigned char *vuv,unsigned char *emit,double *periodic,double *aperiodic) {\\n obs_length=length;obs_count=0;obs_cursor=0;obs_index=index;obs_shift=shift;obs_noise=noise;\\n obs_ap=ratio;obs_norm=norm;obs_vuv=vuv;obs_emit=emit;obs_periodic=periodic;obs_aperiodic=aperiodic;\\n std::memset(periodic,0,length*sizeof(double));std::memset(aperiodic,0,length*sizeof(double));\\n ObservedSynthesis(f0,n,sp,ap,fft,frame,fs,length,wave);\\n return obs_cursor==obs_count?obs_count:-1;\\n}\\n\",\"observe.py\":\"\\\"\\\"\\\"既存768WORLD波形を再構成して同一性を条件に実励振を観測する。\\\"\\\"\\\"\\nfrom paths import *\\nimport ctypes,io,sys,os\\ndef load():\\n    import tempfile\\n    assert Path(tempfile.gettempdir()).resolve()==Path(os.environ['TMPDIR']).resolve()\\n    sys.path[:0]=[str(PERIOD/'runtime-bundle/packages-v2'),str(CONVERT)]\\n    import numpy as np\\n    from scipy import signal\\n    from scipy.io import wavfile\\n    import pyworld\\n    import world_renderer2 as world\\n    binary=Path(pyworld.pyworld.__file__)\\n    ctypes.CDLL(str(binary),mode=ctypes.RTLD_GLOBAL)\\n    lib=ctypes.CDLL(str(HERE/'observer.dylib'))\\n    ptr=ctypes.c_void_p\\n    lib.ObsRun.argtypes=[ptr,ctypes.c_int,ptr,ptr,ctypes.c_int,ctypes.c_double,ctypes.c_int,ctypes.c_int]+[ptr]*10\\n    lib.ObsRun.restype=ctypes.c_int\\n    return np,signal,wavfile,world,lib\\ndef evaluate(item,modules):\\n    np,signal,wavfile,world,lib=modules\\n    for k in ['record','parameters','wave']:assert digest(REPO/item[k])==item[k+'_sha256'],(item['id'],k)\\n    old=read(REPO/item['record']);meta=old['meta']\\n    with np.load(REPO/item['parameters']) as a:\\n        assert all(k in a.files for k in ['mcp','lf0','lpf']),a.files\\n        params=[a[k].copy() for k in ['mcp','lf0','lpf']]\\n    assert meta['settings']['sampling_frequency']==48000 and meta['settings']['fperiod']==240 and meta['settings']['beta']==0\\n    (f0,sp,ap),converted=world.convert(params)\\n    expected=meta['conversion']\\n    factor=float(expected.get('AP_noise_power_factor',1.))\\n    assert factor in [1.,.5]\\n    if factor!=1.:\\n        assert world.ah(ap)==expected['AP_before_sha256']\\n        ap=ap.copy();voiced=f0>0;ap[voiced]*=np.sqrt(factor);np.clip(ap,.001,1.,out=ap)\\n    for k,a in [('f0',f0),('power',sp),('AP',ap)]:assert world.ah(a)==expected[k+'_sha256'],(item['id'],k)\\n    before=[world.ah(x) for x in [f0,sp,ap]]\\n    length=len(f0)*240;raw=np.zeros(length);pc=np.zeros(length);ac=np.zeros(length)\\n    idx=np.zeros(length,dtype=np.int32);shift=np.zeros(length);noise=np.zeros(length,dtype=np.int32)\\n    ratio=np.zeros(length);norm=np.zeros(length);vuv=np.zeros(length,dtype=np.uint8);emit=np.zeros(length,dtype=np.uint8)\\n    pointers=lambda a:np.asarray(a.ctypes.data+np.arange(len(a),dtype=np.uintp)*a.strides[0],dtype=np.uintp)\\n    spp=pointers(sp);app=pointers(ap)\\n    address=lambda a:ctypes.c_void_p(a.ctypes.data)\\n    count=lib.ObsRun(address(f0),len(f0),address(spp),address(app),4096,5.,48000,length,\\n        *[address(a) for a in [raw,idx,shift,noise,ratio,norm,vuv,emit,pc,ac]])\\n    assert count>0 and [world.ah(x) for x in [f0,sp,ap]]==before\\n    assert np.isfinite(raw).all() and np.isfinite(pc).all() and np.isfinite(ac).all()\\n    delta=float(np.max(abs(raw-pc-ac)));assert delta<1e-10\\n    idx=idx[:count];shift=shift[:count];noise=noise[:count];ratio=ratio[:count];norm=norm[:count];emit=emit[:count]\\n    assert np.all(np.diff(idx)>0) and np.all((shift>=0)&(shift<=1/48000))\\n    assert np.array_equal(noise[:-1],np.diff(idx)) and noise[-1]==0\\n    assert np.all(norm[(vuv[idx]==0)|(ratio>.999)]==0)\\n    assert np.array_equal(emit.astype(bool),(vuv[idx]>0)&(norm>0)&(noise>0))\\n    kept=len(params[0])*240\\n    def finish(x):\\n        y=signal.resample_poly(x[:kept],1,2);n=min(round(.012*24000),len(y)//2);env=np.sin(np.linspace(0,np.pi/2,n))**2\\n        y[:n]*=env;y[-n:]*=env[::-1]\\n        return y\\n    audio=(finish(raw)*meta['output_gain']).astype(np.float32);buf=io.BytesIO();wavfile.write(buf,24000,audio)\\n    import hashlib\\n    wavehash=hashlib.sha256(buf.getvalue()).hexdigest();assert wavehash==item['wave_sha256'],('旧波形不一致',item['id'],wavehash,item['wave_sha256'])\\n    ps=finish(pc);as_=finish(ac)\\n    assert len(audio)%120==0\\n    rms=lambda x:np.sqrt(np.mean(x.reshape(-1,120)**2,axis=1))\\n    traces=dict(pulse_index=idx,pulse_fraction_seconds=shift,pulse_noise_size=noise,\\n        pulse_AP_power_at_DC=ratio,pulse_periodic_response_norm2=norm,pulse_periodic_emitted=emit,\\n        sample_vuv_packed=np.packbits(vuv[:kept]),sample_count=np.array([kept]),\\n        periodic_component_rms_5ms=rms(ps),aperiodic_component_rms_5ms=rms(as_),wave_rms_5ms=rms(audio))\\n    result=dict(id=item['id'],cohort=item['cohort'],condition=item['condition'],method=item['method'],\\n        source_parameters_sha256=item['parameters_sha256'],old_wave_sha256=item['wave_sha256'],observed_wave_sha256=wavehash,\\n        wave_byte_exact=True,input_arrays_unchanged=True,component_sum_max_abs_error=delta,\\n        pulses=count,clock_pulses_unvoiced=int((vuv[idx]==0).sum()),\\n        voiced_clock_pulses=int((vuv[idx]>0).sum()),periodic_emitted=int(emit.sum()),\\n        voiced_AP_suppressed=int(((vuv[idx]>0)&(ratio>.999)).sum()),\\n        voiced_zero_periodic_other=int(((vuv[idx]>0)&(ratio<=.999)&(norm==0)).sum()),\\n        last_zero_noise_size=True,AP_noise_power_factor=factor,\\n        source_voiced_frames=int((params[1][:,0]>-1e9).sum()),\\n        observed_voiced_samples=int(vuv[:kept].sum()),sample_count_48k=kept,\\n        emitted_pulses_within_kept_audio=int(emit[idx<kept].sum()),\\n        LF0_not_actual_or_perceived_pitch=True,clock_pulse_not_voiced_excitation=True,\\n        periodic_component_energy_not_perceptual_voicing=True,old_gates_unchanged=True)\\n    return result,traces\\ndef main():\\n    import argparse\\n    p=argparse.ArgumentParser();p.add_argument('stage',choices=['compat','all']);p.add_argument('--job',required=True);a=p.parse_args()\\n    b=Budget();protocol=read(HERE/'protocol.json');mods=load()\\n    rows=protocol['records'] if a.stage=='all' else [protocol['records'][i] for i in protocol['compat_indices']]\\n    results=[]\\n    for item in rows:\\n        target=HERE/'diagnostic'/(item['id']+'.json')\\n        if a.stage=='all' and target.exists():\\n            r=read(target);assert digest(REPO/r['trace_path'])==r['trace_sha256'];results.append(dict(id=r['id'],path=str(target.relative_to(REPO)),sha256=digest(target)));continue\\n        r,traces=evaluate(item,mods)\\n        if a.stage=='compat':results.append(r)\\n        else:\\n            buf=io.BytesIO();mods[0].savez_compressed(buf,**traces);tp=HERE/'trace'/(item['id']+'.npz')\\n            if tp.exists():\\n                with mods[0].load(tp) as x:assert set(x.files)==set(traces) and all(mods[0].array_equal(x[k],v,equal_nan=True) for k,v in traces.items())\\n            else:b.write(tp,buf.getvalue(),a.job)\\n            r.update(trace_path=str(tp.relative_to(REPO)),trace_sha256=digest(tp));b.write_data(target,encode(r),a.job)\\n            results.append(dict(id=r['id'],path=str(target.relative_to(REPO)),sha256=digest(target)))\\n        print('WORLD観測',len(results),'/',len(rows),flush=True)\\n    b.save(HERE/('compatibility-audit.json' if a.stage=='compat' else 'diagnostic-manifest.json'),dict(rows=results,\\n        expected=len(rows),all_wave_byte_exact=True,new_AI=0,old_gates_unchanged=True,\\n        quality_goal_completed=False,protected_confirmation_opened=False),a.job)\\nif __name__=='__main__':main()\\n\",\"prepare.py\":\"\\\"\\\"\\\"固定commitの必要header取得と純粋観測build。初出力前に契約固定。\\\"\\\"\\\"\\nfrom paths import *\\nimport ast,re,subprocess,urllib.request\\nCOMMIT='8d79b88b7dd92e8a132996cf74080b2d6f881b98'\\ndef main():\\n    b=Budget();b.recover()\\n    assert digest(PRIMARY/'synthesis.cpp')=='9888973e28f2194a0eb9807e18e36680f3d912bef3ddf174dc640fedc4e08b4c'\\n    with b.job(NAME,'download','固定WORLD commit必要headerのみ取得',count=200000,reserve_bytes=250000) as j:\\n        pending=['synthesis.h','common.h','constantnumbers.h','matlabfunctions.h'];seen={};total=0\\n        while pending:\\n            name=pending.pop(0)\\n            if name in seen:continue\\n            assert re.fullmatch(r'[a-z_]+\\\\.h',name)\\n            path=HERE/'vendor/world'/name;url=f'https://raw.githubusercontent.com/mmorise/World/{COMMIT}/src/world/{name}'\\n            assert not path.exists()\\n            with urllib.request.urlopen(url,timeout=30) as response:\\n                body=response.read(60001);assert len(body)<=60000\\n            total+=len(body);assert total<=200000\\n            b.write(path,body,j);seen[name]=dict(url=url,sha256=digest(path),bytes=len(body))\\n            pending.extend(re.findall(r'#include\\\\s+\\\"world/([^\\\"]+)\\\"',body.decode()))\\n        b.save(HERE/'header-provenance.json',dict(commit=COMMIT,headers=seen,actual_bytes=total,charged_bytes=200000,maximum_response_bytes=60000),j)\\n    with b.job(NAME,'setup','一次sourceを2つの観測読取hookのみで固定',reserve_bytes=500000) as j:\\n        original=(PRIMARY/'synthesis.cpp').read_text()\\n        n1='      pulse_locations_time_shift, interpolated_vuv);'\\n        n2='  double sqrt_noise_size = sqrt(static_cast<double>(noise_size));'\\n        h1=n1+'\\\\n  ObsTime(number_of_pulses,y_length,pulse_locations_index,pulse_locations_time_shift,interpolated_vuv);'\\n        h2='  ObsResponse(fft_size,noise_size,current_vuv,aperiodic_ratio[0],periodic_response,aperiodic_response);\\\\n'+n2\\n        assert original.count(n1)==1 and original.count(n2)==1\\n        observed=original.replace(n1,h1).replace(n2,h2)\\n        assert observed.replace(h1,n1).replace(h2,n2)==original\\n        b.write(HERE/'synthesis_observed.cpp',observed.encode(),j)\\n        b.write(HERE/'LICENSE-WORLD.txt',(CONVERT/'LICENSE-WORLD.txt').read_bytes(),j)\\n        b.save(HERE/'source-change-audit.json',dict(primary_sha256=digest(PRIMARY/'synthesis.cpp'),commit=COMMIT,\\n            hooks=2,reverse_patch_byte_exact=True,observer_only_writes_own_buffers=True,\\n            original_state_coefficients_random_filter_unchanged=True,installed_binary_direct_trace=False,\\n            recompilation_compatibility_required_for_every_old_wave=True),j)\\n    tool=Path('/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin/clang++')\\n    sdk=Path('/Applications/Xcode.app/Contents/Developer/Platforms/MacOSX.platform/Developer/SDKs/MacOSX.sdk')\\n    assert tool.is_file() and sdk.is_dir()\\n    cmd=[str(tool),'-dynamiclib','-O2','-std=c++11','-fno-modules','-undefined','dynamic_lookup','-isysroot',str(sdk),'-I'+str(HERE/'vendor'),'-I'+str(HERE),str(HERE/'observer.cpp'),'-o',str(HERE/'observer.dylib')]\\n    with b.job(NAME,'setup','観測Cの固定ABI build/外部一時後始末',reserve_bytes=20000000) as j:\\n        with b.workspace(j,'clang中間物とcache',16000000,32000000) as (work,env):\\n            env['CLANG_MODULE_CACHE_PATH']=str(work/'clang-modules')\\n            with b.external_output(HERE/'observer.dylib',200000,j):\\n                result=subprocess.run(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,check=True,timeout=120)\\n        b.save(HERE/'build-audit.json',dict(command=cmd,returncode=result.returncode,stderr=result.stderr,binary_sha256=digest(HERE/'observer.dylib'),all_temporary_removed=True),j)\\n    with b.job(NAME,'setup','全768件観測前のコード/依存/入力hashを固定',reserve_bytes=300000) as j:\\n        for p in HERE.glob('*.py'):ast.parse(p.read_text(),filename=str(p))\\n        inputs={str(p.relative_to(REPO)):digest(p) for p in [PRIMARY/'synthesis.cpp',CONVERT/'world_renderer2.py',PERIOD/'runtime-bundle/manifest.json',ROOT/'campaign-allocation-approval-20261008-0001.json']}\\n        b.save(HERE/'execution-contract.json',dict(registration_sha256=digest(HERE/'registration.json'),protocol_sha256=digest(HERE/'protocol.json'),\\n            source_hashes={str(p.relative_to(HERE)):digest(p) for p in HERE.rglob('*') if p.is_file() and p.suffix in ['.py','.cpp','.h','.dylib']},inputs=inputs,\\n            gates_unchanged=True,quality_goal_completed=False),j)\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\",\"analysis.py\":\"\\\"\\\"\\\"既存WORLD実励振を全件観測・封印する。\\\"\\\"\\\"\\nfrom paths import *\\nimport argparse,subprocess\\ndef verify():\\n    c=read(HERE/'execution-contract.json')\\n    assert digest(HERE/'registration.json')==c['registration_sha256']\\n    assert digest(HERE/'protocol.json')==c['protocol_sha256']\\n    for n,h in c['source_hashes'].items():assert digest(HERE/n)==h,n\\n    for n,h in c['inputs'].items():assert digest(REPO/n)==h,n\\ndef run(stage):\\n    verify();b=Budget();b.recover();p=read(HERE/'protocol.json')\\n    count=4 if stage=='compat' else sum(not (HERE/'diagnostic'/(x['id']+'.json')).exists() for x in p['records'])\\n    assert count>0\\n    with b.job(NAME,'dsp','実周期成分/入力不変/同一波形集計',count=count*4,reserve_bytes=1000000):\\n        with b.job(NAME,'render','観測付き同一WORLD再構成。音声重複保存なし',count=count,reserve_bytes=600000000) as j:\\n            with b.workspace(j,'numpy/WORLD初期化・外部専用cache') as (_,env):\\n                subprocess.run([str(PYTHON),'-B',str(HERE/'observe.py'),stage,'--job',j],env=env,check=True,timeout=10800)\\n    if stage=='compat':assert read(HERE/'compatibility-audit.json')['all_wave_byte_exact']\\n    print(b.reconcile(),flush=True)\\ndef close():\\n    verify();b=Budget();b.recover()\\n    with b.job(NAME,'audit','768同一波形・実周期成分・費用・封印',reserve_bytes=4000000) as j:\\n        rows=[]\\n        for x in read(HERE/'diagnostic-manifest.json')['rows']:\\n            assert digest(REPO/x['path'])==x['sha256'];d=read(REPO/x['path']);assert d['wave_byte_exact']\\n            assert digest(REPO/d['trace_path'])==d['trace_sha256'];rows.append(d)\\n        assert len(rows)==768\\n        keys=['pulses','clock_pulses_unvoiced','voiced_clock_pulses','periodic_emitted','voiced_AP_suppressed','voiced_zero_periodic_other','source_voiced_frames','observed_voiced_samples','sample_count_48k','emitted_pulses_within_kept_audio']\\n        groups={}\\n        for r in rows:groups.setdefault(r['cohort']+'/'+r['method'],[]).append(r)\\n        table={k:dict(files=len(v),**{n:sum(x[n] for x in v) for n in keys}) for k,v in groups.items()}\\n        summary=dict(total=768,all_wave_byte_exact=True,groups=table,maximum_component_sum_error=max(x['component_sum_max_abs_error'] for x in rows),\\n            LF0_not_actual_or_perceived_pitch=True,unvoiced_clock_pulses_not_voiced_excitation=True,\\n            periodic_energy_not_perceived_pitch=True,old_gates_and_decisions_unchanged=True,\\n            observational_existing_corpus_only=True,protected_confirmation_opened=False,quality_goal_completed=False)\\n        b.save(HERE/'aggregate-summary.json',summary,j)\\n        c=b.snapshot()['campaigns'][NAME]\\n        b.save(HERE/'cost-audit.json',dict(campaign=c,actual_reconstruct_calls=c['counts'].get('render',0),new_AI=0,\\n            audio_duplicate_saved=0,all_temporary_removed=True,quality_goal_completed=False),j)\\n        lines=['# WORLDの実励振観測','',\\n            '既存6コホートのWORLD768件を、固定一次実装へ2つの観測hookだけ追加して再構成した。全件で入力3配列と保存済み24kHz WAVのbytehashが一致した。新しい合成係数・採否ゲートはない。','',\\n            '無声区間にも既定500Hzの時計パルスがあるため、時計だけを有声励振としない。周期応答は有声/AP条件でゼロ化され、最終パルスはnoise_size=0で周期寄与がゼロになる。LF0と周期出力寄与を分けた。','',\\n            '|コホート/方式|件数|有声時計パルス|周期寄与あり|APによる抑制|','|---|---:|---:|---:|---:|']\\n        for k,v in table.items():lines.append(f\\\"|{k}|{v['files']}|{v['voiced_clock_pulses']}|{v['periodic_emitted']}|{v['voiced_AP_suppressed']}|\\\")\\n        lines+=['','周期/非周期の成分RMSは観測用派生量で、知覚的有声・瞬時pitchの資格ではない。残響が無励振区間へ広がることも保持した。次は固定支持欠測と実励振の関係を全件照合する。','']\\n        b.write(HERE/'report.md','\\\\n'.join(lines).encode(),j)\\n        files={str(p.relative_to(REPO)):digest(p) for p in HERE.rglob('*') if p.is_file()}\\n        b.save(HERE/'artifact-seal.json',dict(files=files,path_base='repository',experiment_completed=True,quality_goal_completed=False,protected_confirmation_opened=False),j)\\n        b.save(HERE/'completion-audit.json',dict(files_verified=len(files),seal_sha256=digest(HERE/'artifact-seal.json'),all_temporary_removed=True),j)\\n    b.close_campaign(NAME)\\n    with b.locked():\\n        s=b._load();s.setdefault('continuation_checkpoint_history',[]).append(s['continuation_checkpoint'])\\n        s['continuation_checkpoint']=dict(id='world-excitation-completed-20261008-0001',active_campaign=None,campaign_closed=True,\\n            next='commit/push→第27回固定支持欠測と実励振の原因分離',git_save_pending=True,quality_goal_completed=False,protected_confirmation_opened=False);b._write_state(s)\\n    b.save(ROOT/'progress-0037.json',dict(latest_completed=NAME,quality_goal_completed=False,next='第27回固定支持原因分離',budget=b.reconcile()))\\n    print(b.reconcile(),flush=True)\\ndef main():\\n    p=argparse.ArgumentParser();p.add_argument('stage',choices=['compat','all','close']);a=p.parse_args()\\n    close() if a.stage=='close' else run(a.stage)\\nif __name__=='__main__':main()\\n\"}")
def main():
    b=Budget();b.recover();s=b.snapshot()
    assert not s['jobs'] and len(s['campaigns'])==25 and all(c['closed'] for c in s['campaigns'].values())
    assert s['limits']['seconds']-s['seconds']-14400>=14400
    assert shutil.disk_usage(ROOT).free>=20000000000 and shutil.disk_usage(b.guard.root).free>=4000000000
    records=[];seals={}
    for prefix in ['nas-absolute-f0','nas-voicing-ap','nas-vocoder-f0','nas-mcp-postfilter','nas-gv-ablation','nas-gv-ap-interaction']:
        d=ROOT/'campaigns'/(prefix+'-20261008-v1');p=read(d/'protocol.json');seal=read(d/'artifact-seal.json')['files']
        seals[str(d.relative_to(REPO))]=digest(d/'artifact-seal.json')
        for row in p['rows']:
            for condition in p['conditions']:
                for method in p['variants']:
                    if method.startswith('hts'):continue
                    record=d/'render'/row['id']/condition/(method+'.json');x=read(record);params=record.with_suffix('.npz');wave=REPO/x['wav']
                    assert x['status']=='completed'
                    assert digest(record)==seal[str(record.relative_to(REPO))]
                    assert digest(params)==seal[str(params.relative_to(REPO))]
                    assert digest(wave)==x['wav_sha256']==seal[str(wave.relative_to(REPO))]
